import { Link, Route, Router as WouterRouter, Switch, useLocation } from 'wouter';
import { ArrowDownRight, ArrowRight, BadgeCheck, Banknote, Bell, BriefcaseBusiness, Check, ChevronDown, CircleHelp, Clock3, FilePlus2, FileText, Filter, Home, Landmark, LogOut, Menu, Plus, Search, ShieldCheck, Users, WalletCards, X } from 'lucide-react';
import './index.css';

type Status = 'Under Review' | 'Approved' | 'Rejected' | 'Disbursed' | 'Closed';
type Customer = { id:string; firstName:string; lastName:string; dateOfBirth:string; address:string; panNumber:string; panDocumentName?:string; panDocumentDataUrl?:string; phone:string; email:string; username:string; password:string; bankAccountNumber:string; ifscCode:string; bankName:string; registrationDate:string; status:string };
type Loan = { id:string; customerId:string; loanType:string; amount:number; tenureMonths:number; interestRate:number; repaymentFrequency:string; repaymentMethod:string; collateral:string; addressProofName?:string; addressProofDataUrl?:string; comments:string; emi:number; totalRepayment:number; status:Status; createdAt:string; adminComments:string[] };
type Activity = { id:string; label:string; createdAt:string };
type Store = { customers:Customer[]; loans:Loan[]; activity:Activity[]; session:{role:'customer'|'admin'; customerId?:string}|null; pendingCustomerId?:string; successMessage?:string };
