 {id:'C-2064',firstName:'Kabir',lastName:'Nair',dateOfBirth:'1995-05-07',address:'7 Residency Road, Kochi, Kerala',panNumber:'CFJPN2198R',phone:'9895012234',email:'kabir.nair@example.com',username:'kabirn',password:'demo123',bankAccountNumber:'784322001256',ifscCode:'SBIN0007811',bankName:'State Bank of India',registrationDate:'2025-01-12',status:'Active'},
 {id:'C-2072',firstName:'Ananya',lastName:'Iyer',dateOfBirth:'1990-10-19',address:'8 Green Park, Chennai, Tamil Nadu',panNumber:'DPLPI5402L',phone:'9840017654',email:'ananya.iyer@example.com',username:'ananyai',password:'demo123',bankAccountNumber:'324009873211',ifscCode:'AXIS0000922',bankName:'Axis Bank',registrationDate:'2025-02-06',status:'Active'}
